pred_cypher:
MATCH (p:Politician)
WHERE p.name IN ["Valentin State", "Joseph State", "Helen Head", "Bryson Head", "Chris Head", "John Head", "Randall Head", "Richard Head", "Mahlon Head", "Lafayette Head"]
AND EXISTS {
  MATCH (:Country {name: "Rwanda"})-[:hasHeadOfState {start_year: <= 2000, end_year: >= 2000}]->(p)
}
RETURN p.name

CALL {
  MATCH (p:Politician {name: "George Ganchev"})-[:headedBy|memberOf]->(pp:PoliticalParty)
  RETURN pp
}
WITH DISTINCT pp
RETURN count(pp)

CALL {
  MATCH (p:Politician {name: "Lech Kaczyński"})-[:headedBy|foundedBy]->(pp:PoliticalParty)
  RETURN pp
}
WITH DISTINCT pp
RETURN count(pp)

MATCH (p:Politician)-[:holdsPosition]->(pos:Position)
WHERE EXISTS {
  MATCH (p)-[:hasHeadOfState]->(:Country {name: "POL"})
}
RETURN pos.name AS position_name, count(DISTINCT p) AS politician_count
